func foldPairsVecGeneric(res, layer, halfInvTwiddles Vector, alpha *Element) {
	var s, d Element
	for j := range res {
		p, q := &layer[2*j], &layer[2*j+1]
		s.Add(p, q)
		s.Halve()
		d.Sub(p, q)
		d.Mul(&d, &halfInvTwiddles[j]).Mul(&d, alpha)
		res[j].Add(&s, &d)
	}
}

